style.css:
@-moz-document domain("bilibili.com") {
/*
 * Bilibili · 少女漫画杂志（完全改造版）
 * 母题：网点纸背景 + 杂志封面主视觉 + 漫画分镜格卡片 + 拟声字标题 + 贴纸标签。
 * 四色：B站粉 #fb7299 / 墨黑 #2b1b24 / 奶白 #fff8ef / 柠檬黄 #ffd84d
 */

:root {
  --mg-pink: #fb7299;
  --mg-paper: #fffdf8;
  /* 分镜格：3px 墨线 + 粉色硬投影；信息框：3px 墨线 + 墨色硬投影 */
  --mg-panel: 0 0 0 3px #2b1b24, 6px 6px 0 3px #fb7299;
  --mg-panel-hover: 0 0 0 3px #2b1b24, 9px 9px 0 3px #fb7299;
  --mg-box: 0 0 0 3px #2b1b24, 5px 5px 0 3px #2b1b24;
  --mg-sticker: 0 0 0 2px #2b1b24, 3px 3px 0 2px #2b1b24;
}
/* 站点品牌蓝整套换成 B站粉 */
html,
body {
  --brand_blue: #fb7299 !important;
  --v_brand_blue: #fb7299 !important;
  --brand_blue_thin: #ffeef3 !important;
  --Lb1: #ffeef3 !important;
  --Lb2: #ffd1dc !important;
  --Lb3: #ffb3c8 !important;
  --Lb4: #fd8fae !important;
  --Lb5: #fb7299 !important;
  --Lb6: #e85a85 !important;
}

/* ============ 漫画纸：粉色网点 + 奶白纸 + 樱花底 ============ */
html {
  background:
    radial-gradient(circle, rgba(251, 114, 153, 0.26) 1.2px, transparent 1.7px) 0 0 / 9px 9px fixed,
    linear-gradient(rgba(255, 248, 239, 0.66), rgba(255, 248, 239, 0.66)) fixed,
    url("https://cdn.jsdelivr.net/gh/tokeny-ai/anime-userstyles@main/images/bili-bg.webp") center top / cover no-repeat fixed,
    #fff8ef !important;
}
body {
  background: transparent !important;
}
#app,
#i_cecream,
.app-v1,
.bili-feed4,
.bili-header,
.search-layout,
.search-content,
.search-content--gray,
.search-page,
.popular-container,
.space-main,
.bili-footer,
#app::before {
  background: transparent !important;
}

/* ============ 顶栏：奶白纸条 + 墨线下沿 ============ */
.bili-header .bili-header__bar,
.search-fixed-header,
.header-channel {
  background: rgba(255, 248, 239, 0.97) !important;
  box-shadow: 0 3px 0 #2b1b24 !important;
}
.bili-header__bar .left-entry,
.bili-header__bar .left-entry a,
.bili-header__bar .left-entry span,
.bili-header__bar .left-entry svg,
.bili-header__bar .right-entry,
.bili-header__bar .right-entry__item-trigger,
.bili-header__bar .right-entry-text,
.bili-header__bar .right-entry-icon,
.bili-header__bar .right-entry svg {
  color: #2b1b24 !important;
  text-shadow: none !important;
  font-weight: 600 !important;
}
.bili-header__bar .left-entry a:hover,
.bili-header__bar .left-entry a:hover span,
.bili-header__bar .right-entry__item:hover .right-entry-text,
.bili-header__bar .right-entry__item:hover .right-entry-icon {
  color: var(--mg-pink) !important;
}
.bili-header__bar .nav-search-form,
.search-input .search-input-wrap {
  background: #fff !important;
  border: 0 !important;
  border-radius: 999px !important;
  box-shadow: var(--mg-sticker) !important;
}
.search-input .search-input-wrap {
  box-shadow: var(--mg-panel) !important;
}

/* ============ 首页 / 热门：杂志封面主视觉 420px ============ */
.bili-header {
  display: flow-root !important;
}
.bili-header__banner {
  height: 420px !important;
  margin-top: 64px !important;
  min-height: 420px !important;
  background:
    repeating-conic-gradient(from 0deg at 82% 52%, rgba(255, 255, 255, 0.34) 0 1.4deg, transparent 1.4deg 7deg),
    url("https://cdn.jsdelivr.net/gh/tokeny-ai/anime-userstyles@main/images/bili-banner.webp") center 42% / cover no-repeat !important;
  border-bottom: 4px solid #2b1b24 !important;
  overflow: hidden !important;
}
.bili-header__banner .taper-line,
.bili-header__banner .animated-banner,
.bili-header__banner video,
.bili-header__banner canvas,
.bili-header__banner .banner-img img {
  display: none !important;
}
/* 原横幅图层改作左下角的墨色网点（空间页头图同理） */
.bili-header__banner .banner-img,
.space-header .formal-toutu {
  display: block !important;
  inset: 0 !important;
  width: 100% !important;
  height: 100% !important;
  background: radial-gradient(circle, rgba(43, 27, 36, 0.5) 1.6px, transparent 2.2px) 0 0 / 10px 10px !important;
  -webkit-mask-image: linear-gradient(60deg, #000 0%, transparent 40%) !important;
  mask-image: linear-gradient(60deg, #000 0%, transparent 40%) !important;
}
.bili-header__banner .header-banner__inner {
  position: relative !important;
  height: 100% !important;
  z-index: 2 !important;
}
/* 大号 logo：墨线描边 + 粉色错位影 */
.bili-header__banner .inner-logo {
  position: absolute !important;
  left: 72px !important;
  top: 44px !important;
  margin: 0 !important;
  height: auto !important;
  width: auto !important;
}
.bili-header__banner .inner-logo img,
.bili-header__banner .inner-logo .logo-img {
  width: 300px !important;
  height: auto !important;
  filter: drop-shadow(3px 0 0 #2b1b24) drop-shadow(-3px 0 0 #2b1b24) drop-shadow(0 3px 0 #2b1b24)
    drop-shadow(0 -3px 0 #2b1b24) drop-shadow(7px 7px 0 #fb7299) !important;
}
/* 封面口号（首页、热门、空间共用） */
.bili-header__banner .header-banner__inner::before,
.space-header::before {
  content: "今天也是追番好天气";
  position: absolute;
  left: 78px;
  top: 214px;
  z-index: 2;
  font: 900 58px/1.1 "PingFang SC", "Microsoft YaHei", sans-serif;
  letter-spacing: 4px;
  color: #fff;
  text-shadow: 3px 0 0 #2b1b24, -3px 0 0 #2b1b24, 0 3px 0 #2b1b24, 0 -3px 0 #2b1b24,
    3px 3px 0 #2b1b24, -3px -3px 0 #2b1b24, 3px -3px 0 #2b1b24, -3px 3px 0 #2b1b24, 9px 9px 0 #fb7299;
  transform: rotate(-4deg);
  transform-origin: left center;
  pointer-events: none;
}
/* 期号贴纸 */
.bili-header__banner .header-banner__inner::after {
  content: "VOL.1127 · 冬日追番特大号 ♡";
  position: absolute;
  left: 96px;
  top: 318px;
  padding: 6px 16px;
  font: 800 18px/1.2 "PingFang SC", "Microsoft YaHei", sans-serif;
  color: #2b1b24;
  background: #ffd84d;
  box-shadow: var(--mg-sticker);
  transform: rotate(2deg);
  pointer-events: none;
}
/* 大尺寸看板娘：站在右侧，裙摆被下沿裁切（空间页共用） */
.bili-header__banner::after,
.space-header::after {
  content: "";
  position: absolute;
  right: 120px;
  top: 22px;
  width: 300px;
  height: 600px;
  background: url("https://cdn.jsdelivr.net/gh/tokeny-ai/anime-userstyles@main/images/bili-char-1.webp") center top / contain no-repeat;
  filter: drop-shadow(3px 0 0 #fff) drop-shadow(-3px 0 0 #fff) drop-shadow(0 -3px 0 #fff)
    drop-shadow(6px 6px 0 rgba(43, 27, 36, 0.85));
  pointer-events: none;
  z-index: 1;
}
/* 对话气泡 */
.bili-header__banner::before {
  content: "一起追番吧！";
  position: absolute;
  right: 420px;
  top: 70px;
  padding: 14px 26px;
  font: 900 24px/1 "PingFang SC", "Microsoft YaHei", sans-serif;
  color: #2b1b24;
  background: #fff;
  border-radius: 50%;
  box-shadow: 0 0 0 3px #2b1b24, 5px 5px 0 3px #fb7299;
  transform: rotate(-6deg);
  pointer-events: none;
  z-index: 3;
}

/* ============ 频道栏：速度线纸条 + 贴纸按钮 ============ */
.bili-header__channel {
  margin-top: 0 !important;
  padding-top: 6px !important;
  background: repeating-linear-gradient(-62deg, rgba(251, 114, 153, 0.14) 0 3px, transparent 3px 14px),
    rgba(255, 248, 239, 0.9) !important;
  border-bottom: 3px solid #2b1b24 !important;
  margin-bottom: 22px !important;
}
.bili-header__channel .channel-link,
.bili-header__channel .channel-entry-more__link {
  background: #fff !important;
  color: #2b1b24 !important;
  font-weight: 700 !important;
  border-radius: 4px !important;
  box-shadow: var(--mg-sticker) !important;
  transition: transform 0.15s ease, background 0.15s ease !important;
}
.bili-header__channel .channel-link:hover,
.bili-header__channel .channel-entry-more__link:hover {
  background: #ffd84d !important;
  color: #2b1b24 !important;
  transform: rotate(-3deg) scale(1.06) !important;
}
.bili-header__channel .channel-link__right {
  color: #2b1b24 !important;
  font-weight: 600 !important;
}
.bili-header__channel .channel-icons__item .icon-bg {
  background: #fb7299 !important;
  box-shadow: var(--mg-sticker) !important;
}
.bili-header__channel .channel-icons__item:nth-child(2) .icon-bg {
  background: #ffd84d !important;
}
.bili-header__channel .channel-icons__item:nth-child(2) .icon-bg svg {
  color: #2b1b24 !important;
}
.bili-header__channel .channel-icons__item .icon-title {
  font-weight: 800 !important;
  color: #2b1b24 !important;
}

/* ============ 视频卡片 = 漫画分镜格 ============ */
.bili-video-card > .bili-video-card__wrap,
.floor-card-inner,
.popular-list .video-card,
.video-page-card-small,
.bili-bangumi-card {
  background: var(--mg-paper) !important;
  backdrop-filter: none !important;
  border: 0 !important;
  border-radius: 4px !important;
  box-shadow: var(--mg-panel) !important;
  overflow: hidden !important;
  transition: rotate 0.2s ease, scale 0.2s ease, box-shadow 0.2s ease !important;
}
/* 奇偶格错落 ±0.6° */
:nth-child(odd) > .bili-video-card > .bili-video-card__wrap,
.floor-single-card:nth-child(odd) .floor-card-inner,
.popular-list .video-card:nth-child(odd),
.video-page-card-small:nth-child(odd),
.items__item:nth-child(odd) > .bili-bangumi-card {
  rotate: -0.6deg;
}
:nth-child(even) > .bili-video-card > .bili-video-card__wrap,
.floor-single-card:nth-child(even) .floor-card-inner,
.popular-list .video-card:nth-child(even),
.video-page-card-small:nth-child(even),
.items__item:nth-child(even) > .bili-bangumi-card {
  rotate: 0.6deg;
}
.bili-video-card > .bili-video-card__wrap:hover,
.floor-card-inner:hover,
.popular-list .video-card:hover,
.video-page-card-small:hover,
.bili-bangumi-card:hover {
  rotate: 0deg !important;
  scale: 1.03;
  box-shadow: var(--mg-panel-hover) !important;
  z-index: 5;
}
.bili-video-card > .bili-video-card__wrap,
.floor-card-inner {
  padding-bottom: 8px !important;
}
.floor-single-card .floor-card {
  background: transparent !important;
  box-shadow: none !important;
}
/* 封面就是格子里的插图：方角、墨线分隔 */
.bili-video-card__image,
.bili-video-card__image--wrap,
.bili-video-card__cover,
.floor-card-inner .cover-container,
.popular-list .video-card .video-card__content {
  border-radius: 0 !important;
}
.bili-video-card__image,
.bili-video-card__wrap > .bili-video-card__cover,
.floor-card-inner .cover-container {
  border-bottom: 3px solid #2b1b24 !important;
}
.popular-list .video-card .video-card__content {
  box-shadow: 0 0 0 2px #2b1b24 !important;
  overflow: hidden !important;
}
.bili-video-card__info {
  padding: 2px 10px 0 !important;
}
.bili-video-card__info--tit,
.bili-video-card__info--tit a,
.popular-list .video-name,
.video-page-card-small .title,
.bili-bangumi-card__title {
  color: #2b1b24 !important;
  font-weight: 700 !important;
}

/* ============ 贴纸：播放量 / 时长 / 标签 ============ */
.bili-video-card__mask,
.bili-video-card__stats {
  background: none !important;
}
.bili-video-card__stats--item,
.bili-video-card__stats--right {
  padding: 1px 7px !important;
  border-radius: 999px !important;
  background: rgba(43, 27, 36, 0.82) !important;
  color: #fff !important;
  font-weight: 700 !important;
}
.bili-video-card__stats__duration,
.video-page-card-small .duration {
  padding: 1px 7px !important;
  border-radius: 3px !important;
  background: #ffd84d !important;
  color: #2b1b24 !important;
  font-weight: 800 !important;
  box-shadow: 0 0 0 2px #2b1b24 !important;
  rotate: -3deg;
}
.floor-card-inner .badge,
.popular-list .rcmd-tag,
.bili-video-card__info--icon-text {
  background: #ffd84d !important;
  color: #2b1b24 !important;
  border: 0 !important;
  border-radius: 3px !important;
  font-weight: 800 !important;
  box-shadow: 0 0 0 1.5px #2b1b24 !important;
}
.floor-card-inner .badge * {
  color: #2b1b24 !important;
  fill: #2b1b24 !important;
}
.tag-link,
.video-tag-container .tag-link {
  background: #fff !important;
  color: #2b1b24 !important;
  font-weight: 700 !important;
  border-radius: 999px !important;
  box-shadow: var(--mg-sticker) !important;
}
.tag-link:hover {
  background: #ffd84d !important;
}

/* ============ 信息框：墨线方框 + 墨色硬投影 ============ */
.video-info-container,
.video-toolbar-container,
.video-desc-container,
.video-tag-container,
#commentapp,
.up-panel-container,
#danmukuBox,
.space-navbar,
.space-main .section-wrap:not(.top-section),
.aside .home-aside-section,
.nav-tabs,
.vui_tabs,
.search-condition-row,
.recommended-swipe-body {
  background: var(--mg-paper) !important;
  backdrop-filter: none !important;
  border: 0 !important;
  border-radius: 4px !important;
  box-shadow: var(--mg-box) !important;
}

/* ============ 拟声字标题：斜切黄块 + 墨线粗字 ============ */
.section-wrap__title,
.rec-title .title-txt,
.nav-tabs__item--active span,
.vui_tabs--nav-item-active .vui_tabs--nav-text {
  display: inline-block !important;
  padding: 2px 14px !important;
  font-weight: 900 !important;
  font-style: italic !important;
  color: #2b1b24 !important;
  background: #ffd84d !important;
  box-shadow: var(--mg-sticker) !important;
  transform: skew(-10deg) !important;
}
.section-wrap__title {
  font-size: 22px !important;
}
.space-main .section-wrap__header {
  padding-bottom: 10px !important;
  background: repeating-linear-gradient(-62deg, rgba(251, 114, 153, 0.16) 0 3px, transparent 3px 14px) !important;
  border-bottom: 3px solid #2b1b24 !important;
}
.nav-tabs {
  margin-top: 20px !important;
  padding: 0 16px !important;
  background: repeating-linear-gradient(-62deg, rgba(251, 114, 153, 0.14) 0 3px, transparent 3px 14px), #fffdf8 !important;
}
.nav-tabs__item span,
.popular-tips {
  font-weight: 800 !important;
  color: #2b1b24 !important;
}
.nav-tabs__item--active span {
  font-size: 16px !important;
}
.nav-tabs__item--active {
  border-bottom-color: transparent !important;
}

/* ============ 按钮：贴纸 + 按下回弹 ============ */
.bili-header__bar .header-upload-entry,
.vui_button,
.follow-btn,
.space-follow-btn,
.message-btn,
.feed-roll-btn .roll-btn,
.primary-btn {
  border: 0 !important;
  border-radius: 999px !important;
  font-weight: 800 !important;
  box-shadow: var(--mg-sticker) !important;
  transition: translate 0.1s ease, box-shadow 0.1s ease !important;
}
.bili-header__bar .header-upload-entry,
.follow-btn,
.space-follow-btn,
.vui_button--blue,
.vui_pagenation--btn-num.vui_button--active,
.primary-btn {
  background: #fb7299 !important;
  color: #fff !important;
}
.bili-header__bar .header-upload-entry *,
.space-follow-btn * {
  color: #fff !important;
}
.message-btn,
.vui_button:not(.vui_button--blue):not(.vui_button--active),
.feed-roll-btn .roll-btn {
  background: #fff !important;
  color: #2b1b24 !important;
}
.vui_button--active:not(.vui_pagenation--btn-num) {
  background: #ffd84d !important;
  color: #2b1b24 !important;
}
.vui_button:active,
.follow-btn:active,
.space-follow-btn:active,
.message-btn:active,
.header-upload-entry:active {
  translate: 2px 2px;
  box-shadow: 0 0 0 2px #2b1b24, 1px 1px 0 2px #2b1b24 !important;
}

/* ============ 播放页：漫画格播放器 + 标题框 ============ */
#playerWrap {
  border-radius: 4px !important;
  box-shadow: 0 0 0 3px #2b1b24, 8px 8px 0 3px #fb7299 !important;
}
.bpx-player-container {
  border-radius: 4px !important;
  overflow: hidden !important;
}
.video-info-container {
  padding: 10px 18px !important;
  margin: 16px 0 !important;
}
.video-info-container .video-title {
  font-weight: 900 !important;
  color: #2b1b24 !important;
  background: linear-gradient(transparent 62%, #ffd84d 62%) !important;
}
.video-toolbar-container,
.video-desc-container,
.video-tag-container,
#commentapp {
  margin-top: 18px !important;
  padding-left: 18px !important;
  padding-right: 18px !important;
}
.up-panel-container {
  margin-top: 16px !important;
  padding: 10px 12px !important;
}
.video-page-card-small {
  padding: 8px !important;
  margin-bottom: 16px !important;
}
.rec-title {
  margin-bottom: 8px !important;
}

/* ============ 搜索页：集中线 ============ */
.search-header {
  background: repeating-conic-gradient(from 0deg at 50% 22%, rgba(251, 114, 153, 0.16) 0 1.6deg, transparent 1.6deg 8deg) !important;
}
.search-header .search-line,
.space-header .header-upinfo-bg-shadow,
.vui_tabs--nav-bar-active,
.vui_tabs--nav-slider {
  display: none !important;
}
.vui_tabs {
  padding: 0 16px !important;
}

/* ============ 个人空间：同款封面主视觉 ============ */
.space-header {
  margin-top: 64px !important;
  height: 420px !important;
  border-bottom: 4px solid #2b1b24 !important;
  overflow: hidden !important;
}
.space-header .toutu {
  height: 100% !important;
  background:
    repeating-conic-gradient(from 0deg at 58% 50%, rgba(255, 255, 255, 0.32) 0 1.4deg, transparent 1.4deg 7deg),
    url("https://cdn.jsdelivr.net/gh/tokeny-ai/anime-userstyles@main/images/bili-banner.webp") center 42% / cover no-repeat !important;
}
.space-header::before {
  left: 64px;
  top: 64px;
  font-size: 52px;
}
.space-header::after {
  left: 42%;
  right: auto;
}
.space-header .upinfo {
  position: absolute !important;
  left: 0 !important;
  right: 0 !important;
  bottom: 0 !important;
  z-index: 2 !important;
  padding-bottom: 18px !important;
  background: linear-gradient(rgba(43, 27, 36, 0), rgba(43, 27, 36, 0.62)) !important;
}
.space-header .upinfo-detail {
  text-shadow: 0 1px 3px rgba(43, 27, 36, 0.6) !important;
}
.space-navbar {
  margin: 18px 60px 6px !important;
}
.space-main .section-wrap:not(.top-section) {
  padding: 16px 20px !important;
  margin-bottom: 26px !important;
}
.aside .home-aside-section {
  margin-bottom: 20px !important;
}
.aside .home-aside-section > div {
  background: transparent !important;
}

/* ============ 热门页 ============ */
.popular-list .video-card {
  padding: 10px !important;
  height: auto !important;
  margin-bottom: 22px !important;
}

/* ============ 选中色 / 滚动条 ============ */
a:hover {
  color: var(--mg-pink);
}
::selection {
  background: #ffd84d;
  color: #2b1b24;
}
::-webkit-scrollbar { width: 12px; height: 12px; }
::-webkit-scrollbar-track { background: #fff8ef; border-left: 2px solid #2b1b24; }
::-webkit-scrollbar-thumb { background: #fb7299; border: 2px solid #2b1b24; border-radius: 999px; }
}
